corrected_code:
router.patch('/clinical-trials/:trialId/participants/:patientId/daily-log', verifyDoctorSession, async (ctx) => {
  const { trialId, patientId } = ctx.params;
  const { symptoms, adherencePercentage, doctorNotes } = ctx.request.body;

  const assignedParticipant = await TrialParticipant.findOne({
    patientId,
    trialId,
    assignedInvestigatorId: ctx.state.doctor.id
  });
  if (!assignedParticipant) {
    ctx.throw(403, 'Forbidden: participant not under your supervised trial site');
  }

  const logEntry = await DailyTrialLog.findOneAndUpdate(
    { patientId, trialId },
    {
      $set: { symptoms, adherencePercentage, doctorNotes, lastEvaluatedAt: new Date() }
    },
    { new: true }
  );

  if (!logEntry) {
    ctx.throw(404, 'Trial participant log not found');
  }
  ctx.body = logEntry;
});
